from pathlib import Path
from decimal import Decimal
import json,hashlib,datetime
base=Path(__file__).resolve().parents[1]
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
student=base/'student-problems.json';manifest=json.loads((base/'blind-manifest.json').read_text(encoding='utf-8-sig'));assert sha(student)==manifest['studentProblemsSha256']
problem=json.loads(student.read_text(encoding='utf-8-sig'))[0];assert problem['questionNumber']==6 and problem['grade']=='중3' and problem['curriculum']=='2015'
# Independent exact decimal arithmetic on the five printed table entries; no author imports.
xs=['5.10','5.11','5.12','5.13','5.14']; roots=['2.258','2.261','2.263','2.265','2.267']; rows=[]
assert 23*23==529
for index,(x,r) in enumerate(zip(xs,roots),1):
 a=Decimal(r)/10;result=100*a+23;c=int(Decimal(x)*100);v=int(Decimal(r)*1000)
 lower=(2*v-1)**2;upper=(2*v+1)**2;scaled=c*40000
 # (r-.0005)^2 < x < (r+.0005)^2 confirms plausible 3dp table, independent of answer selection.
 assert lower<scaled<upper
 rows.append({'choice':index,'x':x,'printedSqrtApproximation':r,'aApproximation':format(a,'f'),'bExact':23,'computed100aApproxPlusB':format(result,'.2f'),'matchesPrintedTarget':result==Decimal('45.63'),'threeDecimalRootTableCheck':{'method':'Compare squared positive half-thousandth bounds using integers only.','lowerSquaredNumeratorOver4000000':lower,'xNumeratorOver4000000':scaled,'upperSquaredNumeratorOver4000000':upper,'strictlyInside':True}})
matching=[r for r in rows if r['matchesPrintedTarget']];assert len(matching)==1 and matching[0]['choice']==3 and matching[0]['x']=='5.12'
calc={'method':'Python Decimal for printed decimal arithmetic; integer squares for table consistency; no code/root/candidate/private imports and no numerical square-root oracle.','rows':rows,'uniqueChoice':3,'uniqueX':'5.12','status':'passed'}
(base/'solve/calculations.json').write_text(json.dumps(calc,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
sources={n:sha(base/n) for n in ['student-problems.json','blind-manifest.json','SOLVE-BRIEF.md','q06.png']}
exposure={'solverId':'codex-nobyeon-sem1-q06-blind-20261019-r1-independent-01','declaredBeforeReadingStudentFiles':True,'priorExposureToThisNewQuestionAnswerOrAuthorSolution':'none','actualExposure':'Only user task description without numerical answer, then the four authorized student-only files. Earlier M2 curriculum/surface audit concerned a different family, not this new Nobyeon semester1 q06. No parent/root/candidate/private/package/builder/source/author solution opened after blind phase began; no answer search.','phaseBoundary':'M2 report committed5d8be2dc3037deafeb55a7409017a3eaa4510414 before blind phase.','allowedReadFiles':list(sources),'studentSourcesSha256':sources,'manifestPackageDigestReadAsMetadataOnly':manifest['packageDigest'],'notFreshOtherQuestionClaim':True}
(base/'solve/exposure-declaration.json').write_text(json.dumps(exposure,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
solution='두 수 a,b가 양수이므로 b²=529=23²에서 b=23이다. 또한 (√x/10)²=x/100이고 √x/10>0이므로 a=√x/10이다. 표의 √x 근삿값을 s라 쓰면 문제에서 지시한 a의 근삿값은 s/10이고, 그 값으로 계산한 100a+b는 10s+23이다. 주어진 계산 결과가45.63이므로 10s+23=45.63, 10s=22.63, s=2.263이다. 표에서2.263에 대응하는 x는5.12이므로 정답은③이다. 다섯 보기를 각각 확인하면 x=5.10,5.11,5.12,5.13,5.14에서 a의 근삿값은 각각0.2258,0.2261,0.2263,0.2265,0.2267이고, 계산 결과는 각각45.58,45.61,45.63,45.65,45.67이다.45.63을 얻는 것은 세 번째뿐이다. 이 등식은 정확한 a의 값이 아니라 표의 소수값으로 만든 근삿값을 이용한 계산임을 따른다.'
raw={'studentDigest':problem['studentDigest'],'solverId':exposure['solverId'],'answer':'③','solution':solution,'evidence':{'selectedChoice':{'index1based':3,'value':'5.12'},'independentCalculationFile':'calculations.json','independentCalculationSha256':sha(base/'solve/calculations.json'),'allFiveChoicesChecked':rows,'approximateTableSemantics':'The row is explicitly approximate, and the prompt explicitly instructs retaining the printed decimal values and calculating with the approximate a.45.63 is the exact result of that decimal procedure, not an asserted exact100sqrt(x/100)+23. No premature extra rounding or replacement by a calculator root.','existenceUniquenessDomain':'Every offered x is positive, hence x/100 has a unique positive square root a. b=23 is the unique positive root of529. Negative roots are excluded by the printed positivity. All five table approximations are positive and pairwise distinct;10s+23 preserves order, so exactly one can meet45.63, as the exhaustive check establishes. The x-domain is the five listed entries, not an arbitrary real interval. No length or physical unit is printed; all quantities are dimensionless numbers.','gradeConstraints':{'grade':'중3','curriculum':'2015','studentMethods':['positive square-root definition','529=23²','scaling square root by10 verified by squaring','linear equation with decimal coefficients','decimal place-value multiplication/division and table lookup'],'noUpperGradeMethodRequired':True,'verificationOnlyCode':'Decimal arithmetic and integer squared bounds; no calculus, logarithms, general radical expansion, numerical root as answer oracle.'},'actualVisualInspection':{'file':'q06.png','tool':'view_image','observed':'Actual supplied PNG shows q06,4points, the full five-column square-root approximation table, positive a/b conditions and the five choices matching JSON. No geometric figure, extra unit or answer marking. The row says approximate values. Text wraps across lines but no critical numerical condition is obscured.','criticalFindings':[],'pixelCalculationOracle':False,'manifestFigureList':'empty; supplemental PNG is hash-recorded separately, not falsely claimed as a listed manifest figure'},'exposureDeclaration':'exposure-declaration.json','priorAnswerExposure':'none','sourcesSha256':sources,'sourceManifestCheck':'student-problems.json SHA256 equals blind-manifest studentProblemsSha256. studentDigest copied from supplied student record; no private digest algorithm or author package opened.','limits':{'freshBlindSolveOfThisQuestion':True,'authorExposure':False,'privatePacketOpened':False,'operatingDB':0,'productionApproval':False,'rightsApproval':False,'full':0,'loadable':0}},'status':'solved'}
rawpath=base/'solve/q06.json';rawpath.write_text(json.dumps(raw,ensure_ascii=False,indent=2)+'\n',encoding='utf8');assert json.loads(rawpath.read_text(encoding='utf8'))==raw
(base/'solve/own-evidence-manifest.json').write_text(json.dumps({'files':{n:sha(base/'solve'/n) for n in ['q06.json','calculations.json','exposure-declaration.json']},'studentSources':sources,'status':'raw-written-before-any-author-exposure;awaiting-parent-Git-transport-seal'},ensure_ascii=False,indent=2)+'\n',encoding='utf8')
